import json,subprocess,html
from pathlib import Path
R=Path(__file__).resolve().parents[1];E=R/'evidence-v18';native=json.loads((E/'blender-checks.json').read_text());browser=json.loads((E/'browser-checks.json').read_text());capture=json.loads((E/'capture-run.json').read_text());assert len(native['entries'])==len(browser['entries'])==2 and not browser['errors'] and not capture['errors'];probes=[]
for key in ['vivi','vita']:
 p=E/(key+'-run.webm');probe=json.loads(subprocess.check_output(['ffprobe','-v','error','-count_frames','-show_entries','stream=codec_name,width,height,nb_read_frames,avg_frame_rate:format=duration,size','-of','json',str(p)]));assert int(probe['streams'][0]['nb_read_frames'])>1;probes.append({'key':key,**probe})
(E/'video-probes.json').write_text(json.dumps(probes,indent=2)+'\n')
summary={'version':'0.18.0','scope':'Two native body types; local MToon shoulder outline width mask only. Original geometry and all motion unchanged.','passed':{'code_assets':'original binary/geometry/rig/animations/images preserved; exact re-export, edited mask accepted, geometry edit rejected','blender_native':native,'browser_actual':browser,'capture':capture},'failed':{'cuff_subdivision':'New crossings in 6 of 7 Vivi clips; rejected, not selectable. docs/CUFF_REJECTED_V18.json','broad_skin_garment_weight_fits':'Rejected excessive deformation or remaining artifact; docs/TRIALS_V18.json'},'untested':['Blender offline art render','Physical mobile hardware','Godot V18 integration','Human art approval','Vita experimental cuff full collision regression'],'known_defects':['Original shoulder geometry folds and skin self intersections remain','Original cuff polygonal edges remain','CPU recording may drop frames; actual encoding in video-probes.json'],'art_approved':False,'game_ready':False}
(E/'acceptance-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n');frames=json.loads((E/'frame-catalog.json').read_text());parts=['<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>V18 實際瀏覽器驗收畫面</title><style>body{font:16px sans-serif;background:#eef2ee;color:#19251f;margin:24px}img,video{max-width:100%}section{margin:32px 0} .frames{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:12px}</style><h1>V18 實際瀏覽器畫面</h1><p>A：V17；B：局部描邊遮罩候選。幾何摺疊仍在；沒有套用失敗袖口細分。CPU 錄影可能掉格；人工美術、手機真機未測。</p><a href="../web-v18/">回到可操作驗收場</a>']
for key in ['vivi','vita']:parts.append(f'<h2>{key}</h2><video src="{key}-run.webm" controls loop muted></video>')
for s in frames['sequences']:
 parts.append('<section><h2>'+html.escape(s['key']+' · '+s['view'])+'</h2><div class="frames">')
 for f in s['frames']:parts.append('<figure><img loading="lazy" src="'+html.escape(f['file'])+'"><figcaption>'+str(f['time_s'])+' s'+(' · mask '+str(f['outline_mask_enabled']) if 'outline_mask_enabled' in f else '')+'</figcaption></figure>')
 parts.append('</div></section>')
(E/'index.html').write_text(''.join(parts)+'</html>');print('V18_EVIDENCE_INDEX_READY')
